const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict');
const {chromium}=require('playwright');
const root=path.resolve(__dirname,'..'),remote=process.env.TEST_ORIGIN;
const script='/wp-content/plugins/breeze/assets/js/js-front-end/breeze-prefetch-links.min.js_ver=2.5.1';
const style='/wp-content/themes/4050guide/style.css_ver=1.5.4.css';
const rules=new Map();let current;
for(const line of fs.readFileSync(path.join(root,'_headers'),'utf8').split(/\r?\n/)){if(!line.trim()||line.trim().startsWith('#'))continue;if(!/^\s/.test(line)){current=line.trim();rules.set(current,{})}else if(current){const i=line.indexOf(':');if(i>0)rules.get(current)[line.slice(0,i).trim().toLowerCase()]=line.slice(i+1).trim()}}
const server=http.createServer((req,res)=>{const url=new URL(req.url,'http://localhost');let file=path.resolve(root,'.'+decodeURIComponent(url.pathname));if(file!==root&&!file.startsWith(root+path.sep))return res.writeHead(403).end();if(fs.existsSync(file)&&fs.statSync(file).isDirectory())file=path.join(file,'index.html');if(!fs.existsSync(file))return res.writeHead(404).end();const mime={'.html':'text/html','.css':'text/css','.js':'text/javascript','.json':'application/json','.webp':'image/webp','.png':'image/png','.svg':'image/svg+xml'};res.writeHead(200,{'content-type':(mime[path.extname(file)]||'application/octet-stream')+'; charset=utf-8','x-content-type-options':'nosniff',...rules.get(url.pathname)});fs.createReadStream(file).pipe(res)});
async function run(){if(!remote)await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin=remote||'http://127.0.0.1:'+server.address().port,browser=await chromium.launch();try{const page=await browser.newPage(),bad=[],errors=[];
 await page.route('**/*',r=>r.request().url().startsWith(origin)||r.request().url().startsWith('blob:')?r.continue():r.abort());
 page.on('response',r=>{if(r.url().startsWith(origin)&&r.status()>=400)bad.push({url:r.url(),status:r.status()})});page.on('pageerror',e=>errors.push(e.message));
 const resources=[];for(const u of [style,script]){const r=await page.request.get(origin+u);assert.equal(r.status(),200,u);const type=r.headers()['content-type'];assert(u===style?/^text\/css/.test(type):/^(text|application)\/javascript/.test(type),u+' incorrect MIME '+type);resources.push({url:u,status:r.status(),type})}
 for(const width of [390,1440]){await page.setViewportSize({width,height:1000});await page.goto(origin+'/tools/');const css=await page.locator('#guide4050-style-css').evaluate(n=>({href:n.getAttribute('href'),loaded:!!n.sheet,accent:getComputedStyle(document.documentElement).getPropertyValue('--accent')}));assert(css.href.startsWith('/'));assert(css.loaded);assert(css.accent.trim());assert.equal(await page.locator('#budget-total').innerText(),'339,390원');await page.locator('#budget-compare summary').click();assert.equal(await page.locator('#budget-b-total').innerText(),'281,940원');const dl=page.waitForEvent('download');await page.locator('#budget-export').click();assert.equal(await(await dl).failure(),null);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await page.screenshot({path:path.resolve(root,'../4050-traffic-drop-audit-20261109/tools-'+(remote?'live':'local')+'-'+width+'.png')});}
 assert.deepEqual(bad,[]);assert.deepEqual(errors,[]);console.log(JSON.stringify({pass:true,origin,resources,widths:[390,1440],calculator:true,csv:true,badRequests:bad,pageErrors:errors}));
 }finally{await browser.close();if(!remote)await new Promise(r=>server.close(r))}}
run().catch(e=>{console.error(e);process.exitCode=1});
